package com.birdwatcher52.elonhusk;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("elonhusk")
public interface ElonHuskConfig extends Config
{
    @Range(
            min = 50,
            max = 200
    )
    @ConfigItem(
            keyName = "headSize",
            name = "Head Size (%)",
            description = "Controls the size of Elon's head relative to the husk model",
            position = 0
    )
    default int headSize()
    {
        return 100;
    }

    @Range(
            min = -50,
            max = 50
    )
    @ConfigItem(
            keyName = "verticalPosition",
            name = "Vertical Position (%)",
            description = "Moves Elon's head up or down relative to the husk model",
            position = 1
    )
    default int verticalPosition()
    {
        return 0;
    }

    @Range(
            min = 10,
            max = 100
    )
    @ConfigItem(
            keyName = "opacity",
            name = "Opacity (%)",
            description = "Controls the opacity of Elon's head",
            position = 2
    )
    default int opacity()
    {
        return 100;
    }
}

package com.birdwatcher52.elonhusk;

import java.awt.AlphaComposite;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import javax.inject.Inject;

import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class ElonHuskOverlay extends Overlay
{
    /*
     * These define the original/default fit relative to the husk.
     *
     * A Head Size setting of 100% preserves the appearance
     * from the original MVP implementation.
     */
    private static final double BASE_HEIGHT_SCALE = 0.95;
    private static final double BASE_WIDTH_SCALE = 1.05;

    private final ElonHuskPlugin plugin;
    private final ElonHuskConfig config;

    @Inject
    public ElonHuskOverlay(
            ElonHuskPlugin plugin,
            ElonHuskConfig config)
    {
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        BufferedImage image = plugin.getElonImage();

        if (image == null)
        {
            return null;
        }

        for (NPC husk : plugin.getHusks())
        {
            renderElon(graphics, husk, image);
        }

        return null;
    }

    private void renderElon(
            Graphics2D graphics,
            NPC husk,
            BufferedImage image)
    {
        Shape hull = husk.getConvexHull();

        if (hull == null)
        {
            return;
        }

        Rectangle bounds = hull.getBounds();

        if (bounds.width <= 0 || bounds.height <= 0)
        {
            return;
        }

        /*
         * User-configurable size multiplier.
         *
         *  50 = 0.5x
         * 100 = 1.0x
         * 200 = 2.0x
         */
        double userSizeScale =
                config.headSize() / 100.0;

        int maxWidth = Math.max(
                1,
                (int) Math.round(
                        bounds.width
                                * BASE_WIDTH_SCALE
                                * userSizeScale
                )
        );

        int maxHeight = Math.max(
                1,
                (int) Math.round(
                        bounds.height
                                * BASE_HEIGHT_SCALE
                                * userSizeScale
                )
        );

        /*
         * Preserve the PNG's original aspect ratio.
         */
        double widthScale =
                (double) maxWidth / image.getWidth();

        double heightScale =
                (double) maxHeight / image.getHeight();

        double scale = Math.min(
                widthScale,
                heightScale
        );

        int drawWidth = Math.max(
                1,
                (int) Math.round(
                        image.getWidth() * scale
                )
        );

        int drawHeight = Math.max(
                1,
                (int) Math.round(
                        image.getHeight() * scale
                )
        );

        /*
         * Start centered on the husk's projected model.
         */
        int drawX =
                bounds.x
                        + ((bounds.width - drawWidth) / 2);

        int drawY =
                bounds.y
                        + ((bounds.height - drawHeight) / 2);

        /*
         * Vertical position is relative to the current projected
         * height of the husk rather than raw screen pixels.
         *
         * This means the offset naturally scales when the camera
         * zooms in or out.
         *
         * Negative = upward
         * Positive = downward
         */
        double verticalOffsetScale =
                config.verticalPosition() / 100.0;

        int verticalOffset =
                (int) Math.round(
                        bounds.height * verticalOffsetScale
                );

        drawY += verticalOffset;

        /*
         * Apply configurable opacity.
         *
         * Save and restore the previous Composite so this overlay
         * does not affect anything RuneLite renders afterward.
         */
        float alpha =
                config.opacity() / 100.0f;

        Composite oldComposite =
                graphics.getComposite();

        try
        {
            graphics.setComposite(
                    AlphaComposite.getInstance(
                            AlphaComposite.SRC_OVER,
                            alpha
                    )
            );

            graphics.drawImage(
                    image,
                    drawX,
                    drawY,
                    drawWidth,
                    drawHeight,
                    null
            );
        }
        finally
        {
            graphics.setComposite(oldComposite);
        }
    }
}

package com.birdwatcher52.elonhusk;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArraySet;
import javax.imageio.ImageIO;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
        name = "ElonHusk",
        description = "Displays Elon Musk's face over the Husks at Nightmare and Phosani's Nightmare.",
        tags = {"phosani","nightmare","husk","meme","elon","pnm","nm"}
)
public class ElonHuskPlugin extends Plugin
{
    private static final int HUSK_9454 = 9454;
    private static final int HUSK_9455 = 9455;
    private static final int HUSK_9466 = 9466;
    private static final int HUSK_9467 = 9467;

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ElonHuskOverlay overlay;

    private final Set<NPC> husks = new CopyOnWriteArraySet<>();

    private BufferedImage elonImage;

    @Provides
    ElonHuskConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ElonHuskConfig.class);
    }

    @Override
    protected void startUp() throws Exception
    {
        loadElonImage();
        overlayManager.add(overlay);

        if (client.getGameState() == GameState.LOGGED_IN)
        {
            rebuildHusks();
        }
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);

        husks.clear();
        elonImage = null;
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        updateHusk(event.getNpc());
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        husks.remove(event.getNpc());
    }

    @Subscribe
    public void onNpcChanged(NpcChanged event)
    {
        updateHusk(event.getNpc());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            rebuildHusks();
        }
        else
        {
            husks.clear();
        }
    }

    private void updateHusk(NPC npc)
    {
        if (isHusk(npc.getId()))
        {
            husks.add(npc);
        }
        else
        {
            husks.remove(npc);
        }
    }

    private void rebuildHusks()
    {
        husks.clear();

        WorldView worldView = client.getTopLevelWorldView();

        if (worldView == null)
        {
            return;
        }

        for (NPC npc : worldView.npcs())
        {
            if (isHusk(npc.getId()))
            {
                husks.add(npc);
            }
        }
    }

    private void loadElonImage() throws IOException
    {
        try (InputStream input =
                     ElonHuskPlugin.class.getResourceAsStream("/elon.png"))
        {
            if (input == null)
            {
                throw new IOException(
                        "Could not find /elon.png in plugin resources"
                );
            }

            elonImage = ImageIO.read(input);

            if (elonImage == null)
            {
                throw new IOException(
                        "Failed to decode /elon.png"
                );
            }
        }
    }

    private static boolean isHusk(int npcId)
    {
        return npcId == HUSK_9454
                || npcId == HUSK_9455
                || npcId == HUSK_9466
                || npcId == HUSK_9467;
    }

    Set<NPC> getHusks()
    {
        return husks;
    }

    BufferedImage getElonImage()
    {
        return elonImage;
    }
}

package com.birdwatcher52.elonhusk;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ElonHuskPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(ElonHuskPlugin.class);
        RuneLite.main(args);
    }
}
